mapper.delete:
DELETE FROM content_tags WHERE content_id = UUID_TO_BIN(#{contentId}) AND source = 'OPENAPI'
AND tag_id NOT IN ( SELECT id FROM tags WHERE name IN
#{tag.name}
)

mapper.update:
UPDATE tags t JOIN content_tags ct ON ct.tag_id = t.id SET t.content_count = GREATEST(t.content_count - 1, 0) WHERE ct.content_id = UUID_TO_BIN(#{contentId}) AND ct.source = 'OPENAPI'
AND t.name NOT IN
#{tag.name}

UPDATE tags t LEFT JOIN content_tags ct ON ct.tag_id = t.id AND ct.content_id = UUID_TO_BIN(#{contentId}) SET t.content_count = t.content_count + 1 WHERE t.name IN
#{tag.name}
AND ct.tag_id IS NULL

UPDATE content_sports
SET status = CASE
    WHEN #{now} >= TIMESTAMPADD(
        MINUTE,
        CASE
            WHEN LOWER(sport_type) LIKE '%soccer%'
                 OR LOWER(sport_type) LIKE '%football%'
                THEN #{soccerDurationMinutes}
            WHEN LOWER(sport_type) LIKE '%basketball%'
                THEN #{basketballDurationMinutes}
            WHEN LOWER(sport_type) LIKE '%baseball%'
                THEN #{baseballDurationMinutes}
            ELSE #{defaultDurationMinutes}
        END,
        kickoff_at
    ) THEN 'FINISHED'
    ELSE 'LIVE'
END
WHERE status IN ('SCHEDULED', 'LIVE')
  AND kickoff_at <= #{now}
  AND (
      status = 'SCHEDULED'
      OR #{now} >= TIMESTAMPADD(
          MINUTE,
          CASE
              WHEN LOWER(sport_type) LIKE '%soccer%'
                   OR LOWER(sport_type) LIKE '%football%'
                  THEN #{soccerDurationMinutes}
              WHEN LOWER(sport_type) LIKE '%basketball%'
                  THEN #{basketballDurationMinutes}
              WHEN LOWER(sport_type) LIKE '%baseball%'
                  THEN #{baseballDurationMinutes}
              ELSE #{defaultDurationMinutes}
          END,
          kickoff_at
      )
  )
